use super::rgb::Rgb;

/// HSL color: hue in degrees, saturation and lightness as 32-bit floats
/// (mirrors the C++ `HSL` class).
pub struct Hsl {
    pub h: f32,
    pub s: f32,
    pub l: f32,
}

impl Hsl {
    pub fn new(h: f32, s: f32, l: f32) -> Self {
        Hsl { h, s, l }
    }

    /// Convert back to RGB using the classic hue2rgb helper with the
    /// hue normalized to [0, 1].
    pub fn to_rgb(&self) -> Rgb {
        if self.s == 0.0 {
            return Rgb::new(self.l, self.l, self.l);
        }

        let q = if self.l < 0.5 {
            self.l * (1.0 + self.s)
        } else {
            self.l + self.s - self.l * self.s
        };
        let p = 2.0 * self.l - q;

        let hk = self.h / 360.0;
        let tr = hk + 1.0 / 3.0;
        let tg = hk;
        let tb = hk - 1.0 / 3.0;

        Rgb::new(
            hue_to_rgb(p, q, tr),
            hue_to_rgb(p, q, tg),
            hue_to_rgb(p, q, tb),
        )
    }
}

fn hue_to_rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 {
        t += 1.0;
    }
    if t > 1.0 {
        t -= 1.0;
    }
    if t * 6.0 < 1.0 {
        return p + (q - p) * 6.0 * t;
    }
    if t * 2.0 < 1.0 {
        return q;
    }
    if t * 3.0 < 2.0 {
        return p + (q - p) * (2.0 / 3.0 - t) * 6.0;
    }
    p
}

