mod colorspace;

use colorspace::{ColorConverter, Rgb};

/// Parse a float the way C++ `std::stof` does: skip leading whitespace,
/// consume the longest valid float prefix, ignore trailing garbage.
fn stof(s: &str) -> f32 {
    let t = s.trim_start();
    let bytes = t.as_bytes();
    let mut end = 0;
    let mut seen_digit = false;
    let mut i = 0;

    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        i += 1;
    }
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
        seen_digit = true;
    }
    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            seen_digit = true;
        }
    }
    if seen_digit {
        end = i;
        if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
            let mut j = i + 1;
            if j < bytes.len() && (bytes[j] == b'+' || bytes[j] == b'-') {
                j += 1;
            }
            let exp_start = j;
            while j < bytes.len() && bytes[j].is_ascii_digit() {
                j += 1;
            }
            if j > exp_start {
                end = j;
            }
        }
    }

    if end == 0 {
        // std::stof would throw std::invalid_argument and terminate.
        panic!("stof: no conversion could be performed");
    }
    t[..end].parse::<f32>().unwrap()
}

/// Format a float exactly like C++ `std::cout << value` with default
/// settings: printf "%g" semantics with 6 significant digits.
fn fmt_g(v: f32) -> String {
    let d = v as f64;
    if d.is_nan() {
        return "nan".to_string();
    }
    if d.is_infinite() {
        return if d < 0.0 { "-inf".to_string() } else { "inf".to_string() };
    }

    // Exponent of the value rounded to 6 significant digits.
    let sci = format!("{:.5e}", d); // e.g. "4.50000e-1"
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp < -4 || exp >= 6 {
        // Scientific notation; exponent has a sign and at least two digits.
        let mantissa = strip_trailing_zeros(&sci[..epos]);
        format!(
            "{}e{}{:02}",
            mantissa,
            if exp < 0 { '-' } else { '+' },
            exp.abs()
        )
    } else {
        // Fixed notation with 6 significant digits.
        let prec = (5 - exp) as usize;
        strip_trailing_zeros(&format!("{:.*}", prec, d))
    }
}

fn strip_trailing_zeros(s: &str) -> String {
    if s.contains('.') {
        let trimmed = s.trim_end_matches('0');
        trimmed.strip_suffix('.').unwrap_or(trimmed).to_string()
    } else {
        s.to_string()
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut r = 0.5f32;
    let mut g = 0.6f32;
    let mut b = 0.7f32;
    let mut factor = 1.5f32;

    if args.len() > 3 {
        r = stof(&args[1]);
        g = stof(&args[2]);
        b = stof(&args[3]);
    }
    if args.len() > 4 {
        factor = stof(&args[4]);
    }

    let rgb = Rgb::new(r, g, b);
    let result = ColorConverter::adjust_saturation(&rgb, factor);
    println!("{} {} {}", fmt_g(result.r), fmt_g(result.g), fmt_g(result.b));
}

