use std::io::Read;

fn strip(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.strip_suffix('.').unwrap_or(t).to_string()
    } else {
        s.to_string()
    }
}
fn fmt(v: f32) -> String {
    let d = v as f64;
    if !d.is_finite() { return format!("{}", d); }
    let sci = format!("{:.5e}", d);
    let e = sci.find('e').unwrap();
    let x: i32 = sci[e + 1..].parse().unwrap();
    if x < -4 || x >= 6 {
        format!("{}e{}{:02}", strip(&sci[..e]), if x < 0 { '-' } else { '+' }, x.abs())
    } else {
        strip(&format!("{:.*}", (5 - x) as usize, d))
    }
}

fn hue2rgb(p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t * 6.0 < 1.0 { return p + (q - p) * 6.0 * t; }
    if t * 2.0 < 1.0 { return q; }
    if t * 3.0 < 2.0 { return p + (q - p) * (2.0 / 3.0 - t) * 6.0; }
    p
}

// variant bits: 1=tohsl f64, 2=s formula alt, 4=factor f64, 8=torgb f64
fn run(v: u32, r: f32, g: f32, b: f32, f: f32) -> (f32, f32, f32) {
    let (h, s, l);
    let min = r.min(g).min(b);
    let max = r.max(g).max(b);
    if v & 1 != 0 {
        let (r, g, b) = (r as f64, g as f64, b as f64);
        let (min, max) = (min as f64, max as f64);
        let delta = max - min;
        let ll = (max + min) / 2.0;
        if delta == 0.0 {
            h = 0.0f32; s = 0.0f32; l = ll as f32;
        } else {
            let ss = if ll < 0.5 {
                if v & 2 != 0 { delta / (2.0 * ll) } else { delta / (max + min) }
            } else if v & 2 != 0 {
                delta / (2.0 - 2.0 * ll)
            } else {
                delta / (2.0 - max - min)
            };
            let mut hh = if max == r {
                (g - b) / delta
            } else if max == g {
                (b - r) / delta + 2.0
            } else {
                (r - g) / delta + 4.0
            };
            hh *= 60.0;
            if hh < 0.0 { hh += 360.0; }
            h = hh as f32; s = ss as f32; l = ll as f32;
        }
    } else {
        let delta = max - min;
        let ll = (max + min) / 2.0;
        if delta == 0.0 {
            h = 0.0f32; s = 0.0f32; l = ll;
        } else {
            let ss = if ll < 0.5 {
                if v & 2 != 0 { delta / (2.0 * ll) } else { delta / (max + min) }
            } else if v & 2 != 0 {
                delta / (2.0 - 2.0 * ll)
            } else {
                delta / (2.0 - max - min)
            };
            let mut hh = if max == r {
                (g - b) / delta
            } else if max == g {
                (b - r) / delta + 2.0
            } else {
                (r - g) / delta + 4.0
            };
            hh *= 60.0;
            if hh < 0.0 { hh += 360.0; }
            h = hh; s = ss; l = ll;
        }
    }

    let mut s2 = if v & 4 != 0 { (s as f64 * f as f64) as f32 } else { s * f };
    if s2 > 1.0 { s2 = 1.0; }
    if s2 < 0.0 { s2 = 0.0; }

    if s2 == 0.0 {
        return (l, l, l);
    }
    if v & 8 != 0 {
        let (h, s2, l) = (h as f64, s2 as f64, l as f64);
        let q = if l < 0.5 { l * (1.0 + s2) } else { l + s2 - l * s2 };
        let p = 2.0 * l - q;
        let hk = h / 360.0;
        let tr = hk + 1.0 / 3.0;
        let tg = hk;
        let tb = hk - 1.0 / 3.0;
        (
            hue2rgb(p as f32, q as f32, tr as f32),
            hue2rgb(p as f32, q as f32, tg as f32),
            hue2rgb(p as f32, q as f32, tb as f32),
        )
    } else {
        let q = if l < 0.5 { l * (1.0 + s2) } else { l + s2 - l * s2 };
        let p = 2.0 * l - q;
        let hk = h / 360.0;
        (
            hue2rgb(p, q, hk + 1.0 / 3.0),
            hue2rgb(p, q, hk),
            hue2rgb(p, q, hk - 1.0 / 3.0),
        )
    }
}

fn main() {
    let v: u32 = std::env::args().nth(1).unwrap().parse().unwrap();
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    for line in input.lines() {
        let mut it = line.split_whitespace();
        let r: f32 = it.next().unwrap().parse().unwrap();
        let g: f32 = it.next().unwrap().parse().unwrap();
        let b: f32 = it.next().unwrap().parse().unwrap();
        let f: f32 = it.next().unwrap().parse().unwrap();
        let (r, g, b) = run(v, r, g, b, f);
        println!("{} {} {}", fmt(r), fmt(g), fmt(b));
    }
}

