use std::io::Read;

fn strip(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        t.strip_suffix('.').unwrap_or(t).to_string()
    } else {
        s.to_string()
    }
}
fn fmt(v: f32) -> String {
    let d = v as f64;
    if !d.is_finite() { return format!("{}", d); }
    let sci = format!("{:.5e}", d);
    let e = sci.find('e').unwrap();
    let x: i32 = sci[e + 1..].parse().unwrap();
    if x < -4 || x >= 6 {
        format!("{}e{}{:02}", strip(&sci[..e]), if x < 0 { '-' } else { '+' }, x.abs())
    } else {
        strip(&format!("{:.*}", (5 - x) as usize, d))
    }
}

fn hue2rgb(order: bool, p: f32, q: f32, mut t: f32) -> f32 {
    if t < 0.0 { t += 1.0; }
    if t > 1.0 { t -= 1.0; }
    if t * 6.0 < 1.0 {
        return if order { p + (q - p) * t * 6.0 } else { p + (q - p) * 6.0 * t };
    }
    if t * 2.0 < 1.0 { return q; }
    if t * 3.0 < 2.0 {
        return if order { p + (q - p) * 6.0 * (2.0 / 3.0 - t) } else { p + (q - p) * (2.0 / 3.0 - t) * 6.0 };
    }
    p
}

// bits 0-2: tohsl mode; bit3: s formula alt; bit4: factor f64;
// bit5: torgb T1 (degrees then /360); bit6: q formula alt; bit7: branch order
fn run(v: u32, r: f32, g: f32, b: f32, f: f32) -> (f32, f32, f32) {
    let mode = v & 7;
    let min = r.min(g).min(b);
    let max = r.max(g).max(b);
    let (h, mut s, l): (f32, f32, f32);
    let use64 = mode >= 3 && mode <= 5;
    macro_rules! tohsl {
        ($t:ty) => {{
            let (r, g, b) = (r as $t, g as $t, b as $t);
            let (min, max) = (min as $t, max as $t);
            let delta = max - min;
            let ll = (max + min) / 2.0;
            if delta == 0.0 {
                (0.0f32, 0.0f32, ll as f32, 0.0f32)
            } else {
                let ss = if ll < 0.5 {
                    if v & 8 != 0 { delta / (2.0 * ll) } else { delta / (max + min) }
                } else if v & 8 != 0 {
                    delta / (2.0 - 2.0 * ll)
                } else {
                    delta / (2.0 - max - min)
                };
                let (x, sec) = if max == r {
                    ((g - b) / delta, 0.0)
                } else if max == g {
                    ((b - r) / delta, 2.0)
                } else {
                    ((r - g) / delta, 4.0)
                };
                match mode % 3 {
                    0 => {
                        // wrap after *60
                        let mut hh = (x + sec) * 60.0;
                        if hh < 0.0 { hh += 360.0; }
                        (hh as f32, ss as f32, ll as f32, (hh / 360.0) as f32)
                    }
                    1 => {
                        // wrap before *60
                        let mut xx = x + sec;
                        if xx < 0.0 { xx += 6.0; }
                        let hh = xx * 60.0;
                        (hh as f32, ss as f32, ll as f32, (hh / 360.0) as f32)
                    }
                    _ => {
                        // normalized hue directly
                        let mut xx = x + sec;
                        if xx < 0.0 { xx += 6.0; }
                        let hk = xx / 6.0;
                        ((hk * 360.0) as f32, ss as f32, ll as f32, hk as f32)
                    }
                }
            }
        }};
    }
    let (hh, ss, ll, hk0) = if use64 { tohsl!(f64) } else { tohsl!(f32) };
    h = hh; s = ss; l = ll;

    if v & 16 != 0 { s = (s as f64 * f as f64) as f32; } else { s *= f; }
    if s > 1.0 { s = 1.0; }
    if s < 0.0 { s = 0.0; }

    if s == 0.0 { return (l, l, l); }

    let (q, p) = if v & 64 != 0 {
        let q = if l < 0.5 { l + l * s } else { l + s * (1.0 - l) };
        (q, 2.0 * l - q)
    } else {
        let q = if l < 0.5 { l * (1.0 + s) } else { l + s - l * s };
        (q, 2.0 * l - q)
    };

    let order = v & 128 != 0;
    if v & 32 != 0 {
        // T1: channel t's computed in degrees, wrapped, then normalized
        let mut tr = h + 120.0;
        let mut tg = h;
        let mut tb = h - 120.0;
        for t in [&mut tr, &mut tg, &mut tb] {
            if *t < 0.0 { *t += 360.0; }
            if *t > 360.0 { *t -= 360.0; }
            *t /= 360.0;
        }
        (hue2rgb(order, p, q, tr), hue2rgb(order, p, q, tg), hue2rgb(order, p, q, tb))
    } else {
        (
            hue2rgb(order, p, q, hk0 + 1.0 / 3.0),
            hue2rgb(order, p, q, hk0),
            hue2rgb(order, p, q, hk0 - 1.0 / 3.0),
        )
    }
}

fn main() {
    let v: u32 = std::env::args().nth(1).unwrap().parse().unwrap();
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    for line in input.lines() {
